import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.PrintWriter; import java.io.IOException; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); if (n < 5) { out.println("-1"); } else { int[] p = new int[n]; p[0] = 5; p[1] = 1; p[2] = 2; p[3] = 4; p[4] = 3; for (int i = 5; i < n; i++) { p[i] = i + 1; } StringBuilder sb = new StringBuilder(); for (int i = 0; i < n; i++) { sb.append(p[i]).append(i == n - 1 ? "" : " "); } out.println(sb.toString()); } } out.flush(); out.close(); } }